const restoreExtensionDays = `-- name: RestoreExtensionDays :exec
UPDATE availability_calendar
   SET status = CASE WHEN day <= $1::date THEN 'BLOCKED' ELSE 'AVAILABLE' END,
       source = CASE WHEN day <= $1::date THEN 'BOOKING' ELSE 'SYSTEM' END,
       ref_id = CASE WHEN day <= $1::date THEN $2::uuid ELSE NULL END,
       updated_at = $3::timestamptz
 WHERE ref_id = $4::uuid
`

type RestoreExtensionDaysParams struct {
	PreviousBufferEnd time.Time
	BookingID         ids.ID
	Now               time.Time
	ExtensionID       ids.ID
}

// Gives back what an unapplied extension claimed: the booking's previous
// turnover buffer returns to the booking, everything else is freed.
func (q *Queries) RestoreExtensionDays(ctx context.Context, db DBTX, arg RestoreExtensionDaysParams) error {
	_, err := db.Exec(ctx, restoreExtensionDays,
		arg.PreviousBufferEnd,
		arg.BookingID,
		arg.Now,
		arg.ExtensionID,
	)
	return err
}

